// Mantém só arquivos de áudio novos e valida o tamanho (limite do Whisper: 25 MB)
const cfg = $('Config').first().json;
const out = [];
$input.all().forEach((it, i) => {
  const f = it.json;
  const nome = String(f.name || '');
  const mime = String(f.mimeType || '');
  const ehAudio = mime.startsWith('audio/') || /\.(mp3|m4a|wav|ogg|oga|opus|webm|mp4|mpeg|mpga|flac)$/i.test(nome);
  if (!ehAudio) return;
  const tamanho = Number(f.size || 0);
  if (tamanho && tamanho > cfg.MAX_MB * 1024 * 1024) {
    throw new Error(`O áudio "${nome}" tem ${(tamanho / 1048576).toFixed(1)} MB. O Whisper aceita até ${cfg.MAX_MB} MB: salve em MP3 mono de 48 kbps (≈ 70 min) ou divida em partes.`);
  }
  out.push({
    json: {
      fileId: f.id,
      nome,
      base: nome.replace(/\.[^.]+$/, ''),
      pasta: (Array.isArray(f.parents) && f.parents[0]) || cfg.FOLDER_ID
    },
    pairedItem: i
  });
});
return out;

// Ajusta o nome/extensão para formatos aceitos pelo Whisper (.opus/.oga → .ogg)
const item = $input.item;
const bin = item.binary && item.binary.data;
if (!bin) throw new Error('Download do áudio veio vazio.');
if (/\.(opus|oga)$/i.test(bin.fileName || '')) {
  bin.fileName = bin.fileName.replace(/\.(opus|oga)$/i, '.ogg');
  bin.mimeType = 'audio/ogg';
}
if (!/\.[a-z0-9]{2,4}$/i.test(bin.fileName || '')) {
  bin.fileName = (bin.fileName || 'audio') + '.mp3';
}
return item;

// Monta a chamada do Claude que transforma a transcrição em material didático
const a = $('Filtrar Áudio').item.json;
const t = String($input.item.json.data || $input.item.json.text || '').trim();
if (t.length < 300) {
  throw new Error(`Transcrição de "${a.nome}" muito curta (${t.length} caracteres). Confira se o áudio tem fala.`);
}
const system = Buffer.from($('Config').first().json.SYSTEM_PROMPT_B64, 'base64').toString('utf-8');
return {
  json: {
    ...a,
    transcricao: t,
    requestBody: {
      model: 'claude-sonnet-4-5-20250929',
      max_tokens: 16000,
      temperature: 0.3,
      system,
      messages: [{
        role: 'user',
        content: `Arquivo de áudio: ${a.nome}\n\n=== TRANSCRIÇÃO DO ÁUDIO ===\n${t}\n=== FIM DA TRANSCRIÇÃO ===\n\nGere o JSON do material didático.`
      }]
    }
  }
};

// Lê o JSON do Claude e monta o HTML A4 do material
const resp = $input.item.json;
const prev = $('Montar Chamada IA').item.json;
const cfg = $('Config').first().json;

let texto = '';
if (Array.isArray(resp.content)) texto = resp.content.filter(b => b.type === 'text').map(b => b.text).join('');
texto = texto.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
if (resp.stop_reason === 'max_tokens') throw new Error('A resposta da IA foi cortada (limite de tokens). Áudio muito longo: divida em partes.');

let m;
try { m = JSON.parse(texto); }
catch (e) {
  const ini = texto.indexOf('{'), fim = texto.lastIndexOf('}');
  if (ini === -1 || fim <= ini) throw new Error('IA não devolveu JSON: ' + texto.substring(0, 300));
  m = JSON.parse(texto.substring(ini, fim + 1));
}
if (!m.titulo || !Array.isArray(m.secoes) || !m.secoes.length) throw new Error('JSON do material sem título ou sem seções.');

// ═══ MATERIAL DIDÁTICO — ACADEMIA DE POLÍCIA ═══
// Recebe o JSON do material (m) + cfg e devolve o HTML A4 pronto para /html-to-pdf.
function montarHTML(m, cfg) {
  const esc = (s) => String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  // **negrito** e *itálico* depois de escapar
  const fmt = (s) => esc(s)
    .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
    .replace(/(^|[^*])\*(?!\s)(.+?)\*(?!\*)/g, '$1<i>$2</i>')
    .replace(/\n{2,}/g, '</p><p>').replace(/\n/g, '<br>');
  const arr = (x) => Array.isArray(x) ? x : [];

  const bloco = (b) => {
    switch (b.tipo) {
      case 'paragrafo':
        return `<p>${fmt(b.texto)}</p>`;
      case 'lista':
        return `<ul class="lista">${arr(b.itens).map(i => `<li>${fmt(i)}</li>`).join('')}</ul>`;
      case 'destaque':
        return `<div class="box box--chave"><div class="box__rot">${esc(b.titulo || 'Conceito-chave')}</div><p>${fmt(b.texto)}</p></div>`;
      case 'lei':
        return `<div class="box box--lei"><div class="box__rot">Texto da lei</div><p>“${fmt(b.texto)}”</p>${b.fonte ? `<cite>${esc(b.fonte)}</cite>` : ''}</div>`;
      case 'dica':
        return `<div class="box box--dica"><div class="box__rot">${esc(b.titulo || 'Dica do professor')}</div><p>${fmt(b.texto)}</p></div>`;
      case 'atencao':
        return `<div class="box box--atencao"><div class="box__rot">${esc(b.titulo || 'Atenção: pegadinha de prova')}</div><p>${fmt(b.texto)}</p></div>`;
      case 'exemplo':
        return `<div class="box box--exemplo"><div class="box__rot">${esc(b.titulo || 'Exemplo prático')}</div><p>${fmt(b.texto)}</p></div>`;
      case 'passos':
        return `<ol class="passos">${arr(b.itens).map((p, i) =>
          `<li><span class="passos__n">${i + 1}</span><div><b>${esc(p.titulo)}</b>${p.texto ? `<span>${fmt(p.texto)}</span>` : ''}</div></li>`).join('')}</ol>`;
      case 'tabela':
        return `<table class="tab"><thead><tr>${arr(b.colunas).map(c => `<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${
          arr(b.linhas).map(l => `<tr>${arr(l).map(c => `<td>${fmt(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>${
          b.legenda ? `<div class="tab__leg">${esc(b.legenda)}</div>` : ''}`;
      default:
        return b.texto ? `<p>${fmt(b.texto)}</p>` : '';
    }
  };

  const secoes = arr(m.secoes);
  const questoes = arr(m.questoes);
  const letras = 'ABCDE';
  const hoje = new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' });

  const sumario = [
    ...secoes.map((s, i) => `<li><span>${String(i + 1).padStart(2, '0')}</span>${esc(s.titulo)}</li>`),
    arr(m.revisao).length ? `<li><span>R</span>Revisão rápida</li>` : '',
    arr(m.glossario).length ? `<li><span>G</span>Glossário</li>` : '',
    questoes.length ? `<li><span>Q</span>Questões de fixação e gabarito comentado</li>` : ''
  ].join('');

  const corpo = secoes.map((s, i) => `
    <section class="sec">
      <h2><span class="sec__n">${String(i + 1).padStart(2, '0')}</span>${esc(s.titulo)}</h2>
      ${arr(s.blocos).map(bloco).join('\n')}
    </section>`).join('');

  const revisao = arr(m.revisao).length ? `
    <section class="sec">
      <h2><span class="sec__n">R</span>Revisão rápida</h2>
      <ul class="check">${m.revisao.map(r => `<li>${fmt(r)}</li>`).join('')}</ul>
    </section>` : '';

  const glossario = arr(m.glossario).length ? `
    <section class="sec">
      <h2><span class="sec__n">G</span>Glossário</h2>
      <dl class="glos">${m.glossario.map(g => `<div><dt>${esc(g.termo)}</dt><dd>${fmt(g.definicao)}</dd></div>`).join('')}</dl>
    </section>` : '';

  const listaQ = questoes.map((q, i) => `
    <div class="q">
      <div class="q__cab"><span class="q__n">${String(i + 1).padStart(2, '0')}</span>${q.banca ? `<span class="q__banca">${esc(q.banca)}</span>` : ''}</div>
      <p class="q__enun">${fmt(q.enunciado)}</p>
      ${arr(q.alternativas).length
        ? `<ol class="q__alts">${q.alternativas.map((a, j) => `<li><b>${letras[j]}</b>${fmt(String(a).replace(/^\s*[A-Ea-e]\s*[\)\.\-]\s*/, ''))}</li>`).join('')}</ol>`
        : `<div class="q__ce">( &nbsp; ) Certo &nbsp;&nbsp;&nbsp; ( &nbsp; ) Errado</div>`}
    </div>`).join('');

  const gabarito = questoes.map((q, i) => `
    <div class="gab">
      <div class="gab__cab"><span class="q__n">${String(i + 1).padStart(2, '0')}</span><span class="gab__resp">Gabarito: ${esc(q.gabarito)}</span></div>
      <p>${fmt(q.comentario)}</p>
    </div>`).join('');

  const blocoQuestoes = questoes.length ? `
    <section class="sec sec--quebra">
      <h2><span class="sec__n">Q</span>Questões de fixação</h2>
      ${listaQ}
    </section>
    <section class="sec sec--quebra">
      <h2><span class="sec__n">✓</span>Gabarito comentado</h2>
      <div class="gab__grade">${questoes.map((q, i) => `<span><b>${i + 1}</b>${esc(q.gabarito)}</span>`).join('')}</div>
      ${gabarito}
    </section>` : '';

  const css = `
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Space+Grotesk:wght@500;700&display=swap');
@page { size: A4; margin: 16mm 16mm 18mm; }
@page :first { margin: 0; }
:root {
  --preto:#0e0e0e; --grafite:#191919; --ouro:#D4AF37; --ouro2:#b8932a; --ouro-claro:#f7f0da;
  --papel:#ffffff; --texto:#23211d; --suave:#6b665c; --linha:#e6e1d4;
  --laranja:#c2410c; --laranja-claro:#fdf0e7; --azul-claro:#eef3f6;
  --head:'Space Grotesk','Inter',Arial,sans-serif; --body:'Inter',Arial,sans-serif;
}
* { box-sizing:border-box; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
html,body { margin:0; padding:0; }
body { font-family:var(--body); font-size:10.5pt; line-height:1.6; color:var(--texto); background:var(--papel); }
b { font-weight:700; color:#000; } i { font-style:italic; }
p { margin:0 0 9pt; orphans:3; widows:3; }
h1,h2,h3 { font-family:var(--head); margin:0; line-height:1.15; }

/* rodapé fixo em todas as páginas de conteúdo */
.rodape { position:fixed; bottom:-12mm; left:0; right:0; display:flex; justify-content:space-between;
  font-family:var(--head); font-size:7pt; letter-spacing:.14em; text-transform:uppercase; color:var(--suave);
  border-top:1px solid var(--linha); padding-top:5pt; }
.rodape b { color:var(--ouro2); }

/* CAPA */
.capa { position:relative; width:210mm; height:297mm; background:var(--preto); color:#fff; overflow:hidden;
  page-break-after:always; z-index:5; padding:26mm 22mm; display:flex; flex-direction:column; }
.capa::before { content:''; position:absolute; inset:0; background-image:radial-gradient(rgba(212,175,55,.10) 1px, transparent 1px); background-size:9mm 9mm; }
.capa::after { content:''; position:absolute; inset:0; background:radial-gradient(ellipse 70% 45% at 50% 0%, rgba(212,175,55,.20), transparent 70%); }
.capa > * { position:relative; z-index:1; }
.capa__topo { display:flex; align-items:center; justify-content:space-between; }
.capa__marca { font-family:var(--head); font-weight:700; font-size:10pt; letter-spacing:.24em; text-transform:uppercase; display:flex; align-items:center; gap:8pt; }
.capa__marca::before { content:''; width:7pt; height:7pt; background:var(--ouro); box-shadow:0 0 8pt var(--ouro); }
.capa__marca span { color:var(--ouro); }
.capa__logo { width:26mm; height:26mm; object-fit:contain; }
.capa__meio { margin-top:auto; margin-bottom:auto; }
.capa__selo { display:inline-block; font-family:var(--head); font-size:8pt; font-weight:700; letter-spacing:.28em; text-transform:uppercase;
  color:var(--ouro); border:1px solid rgba(212,175,55,.45); padding:5pt 9pt; margin-bottom:16pt; }
.capa h1 { font-size:34pt; font-weight:700; text-transform:uppercase; color:#fff; max-width:150mm; }
.capa h1::after { content:''; display:block; width:22mm; height:3pt; background:var(--ouro); margin-top:14pt; box-shadow:0 0 12pt rgba(212,175,55,.6); }
.capa__sub { font-size:13pt; color:rgba(255,255,255,.75); margin-top:14pt; max-width:140mm; }
.capa__ficha { display:grid; grid-template-columns:repeat(3,1fr); border:1px solid rgba(212,175,55,.35); }
.capa__ficha div { padding:9pt 11pt; border-right:1px solid rgba(212,175,55,.35); }
.capa__ficha div:last-child { border-right:0; }
.capa__ficha span { display:block; font-family:var(--head); font-size:6.5pt; letter-spacing:.2em; text-transform:uppercase; color:rgba(255,255,255,.55); }
.capa__ficha strong { display:block; font-family:var(--head); font-size:10pt; color:var(--ouro); margin-top:3pt; }
.capa__pe { margin-top:14pt; font-size:7.5pt; letter-spacing:.12em; text-transform:uppercase; color:rgba(255,255,255,.45); }

/* abertura */
.abre { border:1px solid var(--linha); border-top:3pt solid var(--ouro); padding:14pt 16pt; margin-bottom:16pt; background:#fcfbf7; }
.abre h3 { font-size:9pt; letter-spacing:.2em; text-transform:uppercase; color:var(--ouro2); margin-bottom:6pt; }
.sumario { list-style:none; margin:0 0 4pt; padding:0; columns:2; column-gap:14pt; }
.sumario li { break-inside:avoid; padding:3pt 0; border-bottom:1px dotted var(--linha); font-size:9.5pt; }
.sumario span { display:inline-block; min-width:18pt; font-family:var(--head); font-weight:700; color:var(--ouro2); }
.obj { list-style:none; padding:0; margin:0; }
.obj li { position:relative; padding-left:15pt; margin-bottom:3pt; }
.obj li::before { content:'▸'; position:absolute; left:0; color:var(--ouro2); }

/* seções */
.sec { margin-bottom:10pt; }
.sec--quebra { page-break-before:always; }
.sec h2 { display:flex; align-items:center; gap:9pt; font-size:15pt; font-weight:700; text-transform:uppercase; color:var(--preto);
  background:var(--preto); color:#fff; padding:8pt 12pt; margin:18pt 0 12pt; page-break-after:avoid; break-after:avoid; }
.sec__n { flex-shrink:0; min-width:22pt; height:22pt; display:inline-grid; place-items:center; padding:0 4pt; background:var(--ouro); color:var(--preto); font-size:11pt; }

.lista { margin:0 0 10pt; padding-left:0; list-style:none; }
.lista li { position:relative; padding-left:14pt; margin-bottom:4pt; }
.lista li::before { content:''; position:absolute; left:2pt; top:6pt; width:5pt; height:5pt; background:var(--ouro); }

.box { position:relative; padding:10pt 13pt; margin:4pt 0 12pt; break-inside:avoid; page-break-inside:avoid; border:1px solid var(--linha); }
.box p:last-child { margin-bottom:0; }
.box__rot { font-family:var(--head); font-size:7.5pt; font-weight:700; letter-spacing:.2em; text-transform:uppercase; margin-bottom:5pt; }
.box--chave { background:var(--ouro-claro); border-color:#e9dbad; border-left:4pt solid var(--ouro); }
.box--chave .box__rot { color:var(--ouro2); }
.box--lei { background:var(--grafite); border-color:var(--grafite); color:#eee; }
.box--lei .box__rot { color:var(--ouro); }
.box--lei p { font-family:Georgia,'Times New Roman',serif; font-style:italic; color:#f1efe9; }
.box--lei b { color:#fff; }
.box--lei cite { display:block; margin-top:6pt; font-style:normal; font-size:8pt; color:var(--ouro); letter-spacing:.04em; }
.box--dica { border-left:4pt solid var(--ouro); }
.box--dica .box__rot { color:var(--ouro2); }
.box--atencao { background:var(--laranja-claro); border-color:#f6cfb4; border-left:4pt solid var(--laranja); }
.box--atencao .box__rot { color:var(--laranja); }
.box--exemplo { background:var(--azul-claro); border-color:#d8e3ea; }
.box--exemplo .box__rot { color:#35536a; }
.box::after { content:''; position:absolute; right:-1px; bottom:-1px; width:8pt; height:8pt; border-right:2pt solid var(--ouro); border-bottom:2pt solid var(--ouro); }

.passos { list-style:none; padding:0; margin:4pt 0 12pt; }
.passos li { display:flex; gap:10pt; align-items:flex-start; padding:7pt 0; border-bottom:1px solid var(--linha); break-inside:avoid; }
.passos__n { flex-shrink:0; width:20pt; height:20pt; display:grid; place-items:center; font-family:var(--head); font-weight:700; color:var(--ouro2); border:1.5pt solid var(--ouro); }
.passos b { display:block; font-family:var(--head); }
.passos span { display:block; color:var(--suave); }

.tab { width:100%; border-collapse:collapse; margin:4pt 0 12pt; font-size:9.5pt; break-inside:avoid; }
.tab th { background:var(--preto); color:var(--ouro); font-family:var(--head); font-size:7.5pt; letter-spacing:.14em; text-transform:uppercase; text-align:left; padding:6pt 8pt; }
.tab td { padding:6pt 8pt; border-bottom:1px solid var(--linha); vertical-align:top; }
.tab tr:nth-child(even) td { background:#faf8f2; }
.tab__leg { font-size:8pt; color:var(--suave); margin:-8pt 0 12pt; }

.check { list-style:none; padding:0; margin:0; display:grid; grid-template-columns:1fr 1fr; gap:6pt; }
.check li { position:relative; padding:7pt 9pt 7pt 26pt; border:1px solid var(--linha); background:#fcfbf7; break-inside:avoid; }
.check li::before { content:'✓'; position:absolute; left:8pt; top:6pt; color:var(--ouro2); font-weight:700; }

.glos { margin:0; }
.glos div { display:grid; grid-template-columns:40mm 1fr; gap:10pt; padding:6pt 0; border-bottom:1px solid var(--linha); break-inside:avoid; }
.glos dt { font-family:var(--head); font-weight:700; }
.glos dd { margin:0; color:var(--suave); }

.q { margin-bottom:14pt; break-inside:avoid; }
.q__cab { display:flex; align-items:center; gap:8pt; background:#f1efe9; padding:4pt 8pt 4pt 0; margin-bottom:6pt; }
.q__n { display:inline-grid; place-items:center; min-width:22pt; height:18pt; background:var(--preto); color:var(--ouro); font-family:var(--head); font-weight:700; font-size:9pt; }
.q__banca { font-family:var(--head); font-size:8pt; letter-spacing:.08em; text-transform:uppercase; color:var(--suave); }
.q__enun { margin-bottom:6pt; }
.q__alts { list-style:none; padding:0; margin:0; }
.q__alts li { display:flex; gap:8pt; padding:2.5pt 0; }
.q__alts li b { flex-shrink:0; width:14pt; height:14pt; display:grid; place-items:center; border:1px solid var(--texto); border-radius:50%; font-size:7.5pt; }
.q__ce { font-family:var(--head); font-size:9pt; }
.gab__grade { display:flex; flex-wrap:wrap; gap:4pt; margin-bottom:14pt; }
.gab__grade span { display:inline-flex; gap:5pt; padding:4pt 8pt; border:1px solid var(--linha); font-family:var(--head); font-size:9pt; }
.gab__grade b { color:var(--ouro2); }
.gab { margin-bottom:10pt; break-inside:avoid; }
.gab__cab { display:flex; align-items:center; gap:8pt; margin-bottom:4pt; }
.gab__resp { font-family:var(--head); font-weight:700; text-transform:uppercase; font-size:9pt; }

.fim { margin-top:18pt; padding:14pt 16pt; background:var(--preto); color:#fff; break-inside:avoid; display:flex; gap:14pt; align-items:center; }
.fim img { width:16mm; height:16mm; object-fit:contain; }
.fim h3 { font-size:11pt; text-transform:uppercase; color:var(--ouro); margin-bottom:3pt; }
.fim p { margin:0; font-size:9pt; color:rgba(255,255,255,.75); }
`;

  return `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(m.titulo)}</title><style>${css}</style></head><body>
<div class="capa">
  <div class="capa__topo">
    <div class="capa__marca">Academia de Polícia <span>GCM</span></div>
    ${cfg.LOGO_URL ? `<img class="capa__logo" src="${esc(cfg.LOGO_URL)}" alt="">` : ''}
  </div>
  <div class="capa__meio">
    <div class="capa__selo">Material didático · ${esc(m.disciplina || 'Guarda Municipal')}</div>
    <h1>${esc(m.titulo)}</h1>
    ${m.subtitulo ? `<p class="capa__sub">${esc(m.subtitulo)}</p>` : ''}
  </div>
  <div class="capa__ficha">
    <div><span>Disciplina</span><strong>${esc(m.disciplina || '—')}</strong></div>
    <div><span>Professor</span><strong>${esc(m.professor || 'Academia de Polícia')}</strong></div>
    <div><span>Leitura</span><strong>${esc(m.duracao_leitura || '—')}</strong></div>
  </div>
  <div class="capa__pe">Preparação Tática · ${esc(hoje)} · ${esc(cfg.SITE_URL || 'academiadepolicia.com.br')}</div>
</div>



<div class="abre">
  ${m.apresentacao ? `<h3>Apresentação</h3><p>${fmt(m.apresentacao)}</p>` : ''}
  ${arr(m.objetivos).length ? `<h3>Ao final deste material você vai</h3><ul class="obj">${m.objetivos.map(o => `<li>${fmt(o)}</li>`).join('')}</ul><br>` : ''}
  <h3>Sumário</h3><ul class="sumario">${sumario}</ul>
</div>

${corpo}
${revisao}
${glossario}
${blocoQuestoes}

<div class="fim">
  ${cfg.LOGO_URL ? `<img src="${esc(cfg.LOGO_URL)}" alt="">` : ''}
